{"explanation":"A cylinder's volume is base area times height: V = πr²h. A cone with the same base and height holds exactly one third of that — pour three cone-fulls of sand or water into the cylinder and it fills perfectly to the top. The deeper reason: at a fraction t of the way from apex to base, the cone's cross-section has radius t·r, hence area t²·πr²; averaging t² from 0 to 1 gives exactly 1/3, so V_cone = (1/3)πr²h. The animation pours 3 cones into the cylinder, then lets you explore with a slider or by clicking the cone.","manimCode":"function ellipsePts(cx, cy, rx, ry, n) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * 2 * Math.PI;
    pts.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a), 0]);
  }
  return pts;
}

const cylCx = -3.4, coneCx = 3.0;
const R = 1.4, RY = 0.35;
const baseY = -1.8, topY = 2.0, H = topY - baseY;
const y1 = baseY + H / 3, y2 = baseY + 2 * H / 3;

const title = new Text({ text: 'A cone = 1/3 of its cylinder', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.45, 0]);

// --- cylinder ---
const cylBody = new Polygon({ vertices: [[cylCx - R, baseY, 0], [cylCx + R, baseY, 0], [cylCx + R, topY, 0], [cylCx - R, topY, 0]], color: WHITE });
cylBody.setFill(BLUE_E, 0.12);
cylBody.setStrokeWidth(2);
const cylTop = new Polygon({ vertices: ellipsePts(cylCx, topY, R, RY, 48), color: WHITE });
cylTop.setFill(BLACK, 1);
cylTop.setStrokeWidth(2);
const cylBot = new Polygon({ vertices: ellipsePts(cylCx, baseY, R, RY, 48), color: WHITE });
cylBot.setFillOpacity(0);
cylBot.setStrokeWidth(2);

// --- cone (same base, same height) ---
const coneTri = new Polygon({ vertices: [[coneCx, topY, 0], [coneCx - R, baseY, 0], [coneCx + R, baseY, 0]], color: ORANGE });
coneTri.setFill(ORANGE, 0.25);
coneTri.setStrokeWidth(2);
const coneBase = new Polygon({ vertices: ellipsePts(coneCx, baseY, R, RY, 48), color: ORANGE });
coneBase.setFill(BLACK, 0.85);
coneBase.setStrokeWidth(2);
const coneH = new Line({ start: [coneCx, topY, 0], end: [coneCx, baseY, 0], color: GRAY });
coneH.setStrokeWidth(1.5);

// --- third-level markers ---
const mk1 = new Line({ start: [cylCx - R, y1, 0], end: [cylCx + R, y1, 0], color: GRAY });
mk1.setStrokeWidth(1);
const mk2 = new Line({ start: [cylCx - R, y2, 0], end: [cylCx + R, y2, 0], color: GRAY });
mk2.setStrokeWidth(1);
const ml1 = new Text({ text: '1 cone', color: GRAY, fontSize: 18 });
ml1.moveTo([cylCx + R + 0.95, y1, 0]);
const ml2 = new Text({ text: '2 cones', color: GRAY, fontSize: 18 });
ml2.moveTo([cylCx + R + 0.95, y2, 0]);
const ml3 = new Text({ text: '3 cones', color: GRAY, fontSize: 18 });
ml3.moveTo([cylCx + R + 0.95, topY, 0]);

// --- annotations: radius, height, equal-height connector ---
const rLine = new Line({ start: [cylCx, topY, 0], end: [cylCx + R, topY, 0], color: YELLOW });
rLine.setStrokeWidth(3);
const rLab = new Text({ text: 'r', color: YELLOW, fontSize: 22 });
rLab.moveTo([cylCx + R / 2, topY + 0.28, 0]);
const hLine = new Line({ start: [cylCx - R - 0.4, baseY, 0], end: [cylCx - R - 0.4, topY, 0], color: WHITE });
hLine.setStrokeWidth(2);
const hLab = new Text({ text: 'h', color: WHITE, fontSize: 22 });
hLab.moveTo([cylCx - R - 0.75, 0.1, 0]);
const cRLine = new Line({ start: [coneCx, baseY, 0], end: [coneCx + R, baseY, 0], color: YELLOW });
cRLine.setStrokeWidth(3);
const cRLab = new Text({ text: 'r', color: YELLOW, fontSize: 22 });
cRLab.moveTo([coneCx + R / 2 + 0.15, baseY + 0.32, 0]);
const coneHLab = new Text({ text: 'h', color: GRAY, fontSize: 22 });
coneHLab.moveTo([coneCx + 0.28, 0.1, 0]);
const conn = new Line({ start: [cylCx, 2.6, 0], end: [coneCx, 2.6, 0], color: GRAY });
conn.setStrokeWidth(1.5);
const tick1 = new Line({ start: [cylCx, 2.45, 0], end: [cylCx, 2.75, 0], color: GRAY });
tick1.setStrokeWidth(1.5);
const tick2 = new Line({ start: [coneCx, 2.45, 0], end: [coneCx, 2.75, 0], color: GRAY });
tick2.setStrokeWidth(1.5);
const connLab = new Text({ text: 'same height', color: GRAY, fontSize: 20 });
connLab.moveTo([(cylCx + coneCx) / 2, 2.92, 0]);

// --- liquid fill inside cylinder ---
const liquid = new Polygon({ vertices: [[cylCx - R, baseY, 0], [cylCx + R, baseY, 0], [cylCx + R, baseY + 0.002, 0], [cylCx - R, baseY + 0.002, 0]], color: BLUE_C });
liquid.setFill(BLUE, 0.55);
liquid.setStrokeWidth(2);

// --- dynamic status text (remove + recreate pattern) ---
let status = null;
let lastMsg = '';
function updateStatus(msg, col) {
  if (msg === lastMsg) return;
  lastMsg = msg;
  if (status) scene.remove(status);
  status = new Text({ text: msg, color: col || WHITE, fontSize: 24 });
  status.moveTo([0, -3.45, 0]);
  scene.add(status);
}

let poured = 0;
function setPour(v) {
  poured = Math.max(0, Math.min(3, v));
  const frac = poured / 3;
  const yT = baseY + Math.max(frac, 0.0005) * H;
  liquid.setVertices([[cylCx - R, baseY, 0], [cylCx + R, baseY, 0], [cylCx + R, yT, 0], [cylCx - R, yT, 0]]);
  const pct = Math.round(frac * 100);
  updateStatus(poured.toFixed(1) + ' cones poured  \u2192  ' + pct + '% full');
}

async function pourTo(target, dur) {
  const start = poured;
  const steps = Math.max(1, Math.round(dur / 0.04));
  for (let i = 1; i <= steps; i++) {
    setPour(start + (target - start) * (i / steps));
    await scene.wait(dur / steps);
  }
}

// --- build the scene ---
await scene.play(new Write(title));
await scene.play(new AnimationGroup([new Create(cylBody), new Create(coneTri)]));
scene.add(liquid);
await scene.play(new AnimationGroup([
  new FadeIn(cylTop), new FadeIn(cylBot), new FadeIn(coneBase), new FadeIn(coneH),
  new FadeIn(mk1), new FadeIn(mk2), new FadeIn(ml1), new FadeIn(ml2), new FadeIn(ml3),
  new FadeIn(rLine), new FadeIn(rLab), new FadeIn(hLine), new FadeIn(hLab),
  new FadeIn(cRLine), new FadeIn(cRLab), new FadeIn(coneHLab),
  new FadeIn(conn), new FadeIn(tick1), new FadeIn(tick2), new FadeIn(connLab)
]));

const fCyl = new MathTex({ latex: 'V_{cyl} = \\pi r^2 h' });
await fCyl.waitForRender();
fCyl.setColor(BLUE_C);
fCyl.moveTo([cylCx, -2.75, 0]);
const fCone = new MathTex({ latex: 'V_{cone} = \\frac{1}{3} \\pi r^2 h' });
await fCone.waitForRender();
fCone.setColor(ORANGE);
fCone.moveTo([coneCx, -2.75, 0]);
await scene.play(new AnimationGroup([new Write(fCyl), new Write(fCone)]));

// --- guided demo: pour 3 cones ---
updateStatus('Pouring cone #1...');
await pourTo(1, 1.1);
updateStatus('1 cone fills exactly 1/3 of the cylinder', YELLOW);
await scene.wait(1);
updateStatus('Pouring cone #2...');
await pourTo(2, 1.1);
updateStatus('2 cones fill 2/3 of the cylinder', YELLOW);
await scene.wait(1);
updateStatus('Pouring cone #3...');
await pourTo(3, 1.1);
updateStatus('3 cones fill the cylinder exactly!', GREEN);
await scene.wait(1.6);
updateStatus('Now drag the slider or click the cone!');

// --- interactivity ---
const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Cones poured', min: 0, max: 3, value: 3, step: 0.05, onChange: function(v) { setPour(v); } });
controls.addButton({ label: 'Pour 1 cone', onClick: function() { setPour(Math.min(3, poured + 1)); } });
controls.addButton({ label: 'Empty', onClick: function() { setPour(0); } });

const pourClick = function() { setPour(Math.min(3, poured + 1)); };
makeClickable(coneTri, scene, { onClick: pourClick });
makeClickable(coneBase, scene, { onClick: pourClick });
makeHoverable(coneTri, scene, { hoverScale: 1.04, cursor: 'pointer' });
makeHoverable(coneBase, scene, { hoverScale: 1.04, cursor: 'pointer' });

await scene.wait(999999);"}

